light 49.5 65.8 56.5 color=1,0.95,0.85 power=5 angle=140 reach=10 baked
light 56.5 65.8 63.5 color=1,0.95,0.85 power=5 angle=140 reach=10 baked
light 56.5 65.8 49.5 color=1,0.95,0.85 power=5 angle=140 reach=10 baked
light 63.5 68.8 56.5 color=0.8,0.95,1 power=5 angle=140 reach=10 baked
light 49.5 68.8 56.5 color=0.8,0.95,1 power=5 angle=140 reach=10 baked
light 56.5 68.8 63.5 color=0.8,0.95,1 power=5 angle=140 reach=10 baked
light 56.5 68.8 49.5 color=0.8,0.95,1 power=5 angle=140 reach=10 baked
